import{_ as i,h as o,i as e,c as E,v as l,p as n,x as t,m as s,e as p,S as P}from"./chunks/framework.Dvtg8yj2.js";const _=JSON.parse('{"title":"光学邻近修正 OPC","description":"","frontmatter":{"title":"光学邻近修正 OPC","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/opc.md","filePath":"llm/opc.md","lastUpdated":1788454257000}'),h={name:"llm/opc.md"};function d(A,a,m,C,c,O){const r=o("Mermaid");return e(),E("div",null,[a[1]||(a[1]=l('<h1 id="光学邻近修正-opc" tabindex="-1">光学邻近修正 OPC <a class="header-anchor" href="#光学邻近修正-opc" aria-label="Permalink to &quot;光学邻近修正 OPC&quot;">​</a></h1><div class="epigraph"><p>掩模上的图形并不是晶圆上要的图形。衍射、透镜、抗蚀剂与蚀刻都会把邻域写进每条边；修正的对象是这个邻域算子，而不是单条边的宽度。</p><footer>—— 对照 Chris A. Mack 对光学邻近效应与分辨率增强的论述</footer></div><p>投影光刻是低通系统。瑞利尺度 \\(k_1\\lambda/\\mathrm{NA}\\) 附近，孤立线与密线的空中像对比、线端缩短、拐角圆化会按邻域几何而变。光学邻近修正（Optical Proximity Correction, OPC）在掩模上预畸变多边形，使显影或蚀刻后的轮廓贴近设计目标。它不是美化版图，而是把成像与工艺的前向模型求一个可制造的逆。规则表能覆盖早期节点；模型基 OPC 成为 65 nm 之后的默认，并在 EUV 上与<a href="/llm/smo">光源掩模协同优化</a>、<a href="/llm/ilt-curvilinear">逆光刻</a>连成一条计算链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一条设计宽度，放到密线阵列里和放到孤立环境里，印出的 CD 可以差出工艺窗口的一截。原因有三层。光学：部分相干照明下，邻线的衍射级在瞳面重叠不同，空中像不同。抗蚀剂：酸扩散或团簇统计把空中像再糊一次，见 <a href="/llm/euv-resist">EUV 胶</a>。蚀刻：密度相关的微负载、聚合物沉积，把显影轮廓再偏一截。若不在掩模上补偿，设计规则只能靠放宽间距硬挡，密度与性能一起丢。</p><p>早期规则 OPC 用查表：对边、线端、拐角加固定衬线或内缩。图形一复杂，邻域组合爆炸，表无法覆盖。必须改成：用紧凑成像模型反复模拟—移动边—再模拟，直到边缘放置误差（EPE）落到容差内。问题因此是全芯片的逆问题近似，计算预算与模型误差同时在场。</p><h3 id="邻近效应是卷积-不是本地偏置" tabindex="-1">邻近效应是卷积，不是本地偏置 <a class="header-anchor" href="#邻近效应是卷积-不是本地偏置" aria-label="Permalink to &quot;邻近效应是卷积，不是本地偏置&quot;">​</a></h3><p>Hopkins 成像把空中像写成互强度与掩模透过率的双线性形式；在固定光源与瞳下，可收成 TCC 与掩模频谱的运算。某点的强度依赖周围一个光学直径（数个波长量级）内的全部开口。把 OPC 理解成「每条边加一个经验纳米数」，会修对一维线、修不对二维热区。正确的对象是邻域算子：边怎么切碎、助条放哪、要不要动光源，都是在给这个算子找逆。</p><p><span class="marginnote">OPC 修的是「印出来像不像目标」，不是「掩模是不是设计的相似变换」。掩模上出现的衬线、锤头、亚分辨助条（SRAF）在晶圆上并不作为独立图形存在；它们只改变目标图形的空中像与工艺窗口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型基 OPC 的主循环是：把设计多边形切成边碎片（fragment），对每个碎片求当前模拟轮廓相对目标的 EPE，沿法向移动碎片，迭代至收敛或撞上掩模规则（MRC）。模型分两段：光学（光源、NA、薄膜栈、EUV 的掩模三维与阴影）和抗蚀剂/蚀刻（紧凑模型或经验偏置）。SRAF 另开一轨：在主图形旁插入印不出来的细条，抬高焦点与剂量窗口，再交给主循环微调。</p><p>EUV 上还要加掩模 3D：反射多层膜、吸收体厚度、斜入射造成的阴影随图形取向而变。用 DUV 透射薄掩模假设做 EUV OPC，会出现系统性的左右不对称与取向相关偏置。全芯片迭代次数、碎片长度、是否对热区加密，直接决定 CPU/GPU 小时，见 <a href="/llm/computational-litho-gpu">计算光刻加速</a>。</p><h3 id="碎片、助条与工艺窗口带" tabindex="-1">碎片、助条与工艺窗口带 <a class="header-anchor" href="#碎片、助条与工艺窗口带" aria-label="Permalink to &quot;碎片、助条与工艺窗口带&quot;">​</a></h3><p>碎片太长，弯角与线端动不了；太短，变量爆炸、还容易做出 MRC 违例的尖角。SRAF 太靠近主图形会印出来，太远则无效；放置本身已是组合优化。评价不能只看名义剂量、名义焦点的轮廓，而要看工艺窗口带（PV-band）：剂量与焦点在规格矩形里扫一圈，轮廓包络是否仍让出套刻与电学余量。OPC 若只拟合中心点，窗口边沿会先死。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每一次边移动都在改掩模频谱。低频分量主要调 CD，高频分量调拐角与助条。投影透镜会丢掉超出 NA 的级次，所以掩模上的锐角并不会原样出现在空中像里——这正是后来曲线掩模可以比曼哈顿更「顺」的原因：与其用大量小矩形去逼一个透镜本来就会滤掉的高频，不如直接用透镜通带里更有效的形状，见 <a href="/llm/ilt-curvilinear">ILT</a>。OPC 仍用曼哈顿多边形，是因为传统可变成形束（VSB）写掩模按矩形炮计数；计算与掩模写入被同一离散化绑在一起。</p><p>抗蚀剂模型把连续空中像变成可移动的「边」。阈值模型假设某一强度等高线即轮廓；更认真的模型含扩散与显影速率。模型校在特定胶、特定层、特定蚀刻上，换胶或换硬掩模等于作废。因此 OPC 不是可移植的软件功能，而是与工艺绑定的校准物。</p><p><span class="marginnote">把 OPC 当成「设计完成后的装饰」会低估它的位置。设计规则、标准单元库和 SRAM 位元，都已经按「这类 OPC 能收住什么」来画。库与 OPC 脱节时，不是后期多跑一夜计算能补上的。</span></p><h3 id="与-ret-家族的分工" tabindex="-1">与 RET 家族的分工 <a class="header-anchor" href="#与-ret-家族的分工" aria-label="Permalink to &quot;与 RET 家族的分工&quot;">​</a></h3><p>离轴照明、相移掩模、SMO、多重图形，都是分辨率增强（RET）。OPC 是其中必须落地到每条边的那一层：光源与相移决定你有什么样的空中像家族，OPC 在这个家族里把每块版图修到可印。没有 OPC 的极端照明会把工艺窗口做成实验室演示；没有合适照明的 OPC 会把掩模修成无法写入的碎形。工程顺序通常是：先 SMO 定光源与设计规则，再全芯片 OPC，对窗口仍不够的热区上 ILT。</p>',20)),(e(),n(P,null,{default:t(()=>[p(r,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20LR%0A%20%20DES%5B%22%E8%AE%BE%E8%AE%A1%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20FRAG%5B%22%E5%88%87%E7%A2%8E%E7%89%87%22%5D%0A%20%20FRAG%20--%3E%20SIM%5B%22%E5%85%89%E5%AD%A6%2B%E8%83%B6%2B%E8%9A%80%E5%88%BB%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20SIM%20--%3E%20EPE%5B%22%E7%AE%97%20EPE%20%2F%20PV-band%22%5D%0A%20%20EPE%20--%3E%20MOVE%5B%22%E7%A7%BB%E5%8A%A8%E8%BE%B9%20%2F%20%E6%94%BE%20SRAF%22%5D%0A%20%20MOVE%20--%3E%20MRC%5B%22%E6%8E%A9%E6%A8%A1%E8%A7%84%E5%88%99%E6%A3%80%E6%9F%A5%22%5D%0A%20%20MRC%20--%3E%20FRAG%0A%20%20MRC%20--%3E%20MASK%5B%22%E5%8F%AF%E5%86%99%E6%8E%A9%E6%A8%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>OPC 假定前向模型够准。未建模的透镜像差、掩模三维残差、随机胶效应，都会变成「修不掉」的系统偏差或噪声。随机缺失孔不是均值轮廓问题，均值 OPC 加再多衬线也抹不平泊松尾，那要胶、剂量与检测一起收。计算上，碎片级迭代对全芯片是 \\(10^{12}\\) 量级的前向求值，必须分层、补丁和 GPU；否则 TAPOUT 日历过不去。</p><p>不要把 OPC 与设计规则检查混为一谈。DRC 保证拓扑与间距在库合同内；OPC 保证在合同内的图形能印出来。DRC 干净但 OPC 后 MRC 爆掉，掩模厂仍拒收。曲线 ILT 会把这条边界再推一截，但前提是<a href="/llm/multibeam-mask-writer">多束写掩模</a>接得住。</p><p><span class="marginnote">报告「OPC 后 CD 误差」时要写清：是名义条件还是 PV-band，是晶圆 SEM 还是纯模拟，是否含蚀刻。只报名义模拟 EPE，等于只报训练集 loss。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OPC 在掩模上预畸变，补偿光学邻近、抗蚀剂与蚀刻把邻域写进轮廓的效应。</li><li>模型基方法切边迭代最小化 EPE，并用 SRAF 换工艺窗口，而不是只拟合中心点。</li><li>成像是邻域算子；把 OPC 当成本地偏置会修不对二维热区。</li><li>EUV 必须把掩模 3D 与阴影打进模型，DUV 薄掩模假设会留下取向误差。</li><li>计算量与校准绑定工艺；换胶、换照明、换蚀刻都要重做。</li><li>热区与曲线掩模把 OPC 推向 ILT 与多束写入。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；计算光刻与 RET 公开文献。</li></ul>',6))])}const f=i(h,[["render",d]]);export{_ as __pageData,f as default};
